export default router;`},{id:"step_5",stepNumber:5,name:"authenticate()",type:"middleware",category:"Auth Middleware",filePath:"backend/middleware/auth.js",line:12,params:["req: Request","res: Response","next: NextFunction"],calls:["jwt.verify()","next()"],calledBy:["itemRoutes.js:21"],apiEndpoint:"POST /api/items",dbOperation:"Optional User.findById(decoded.id)",branchConditions:['if (!authHeader?.startsWith("Bearer ")) -> 401 Unauthorized',"if (jwt.verify fails / expired) -> 401 Invalid Token"],errorHandling:"Returns HTTP 401 JSON immediately; blocks downstream controller execution.",summary:"Verifies the HMAC-SHA256 signature of the JWT token, extracts user ID, and attaches user context to req.user.",codeSnippet:`// backend/middleware/auth.js:12
import jwt from 'jsonwebtoken';

export function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, message: 'Authorization token required.' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ success: false, message: 'Session expired. Please log in again.' });
  }
}`},{id:"step_6",stepNumber:6,name:"createItem()",type:"controller",category:"Controller Logic",filePath:"backend/controllers/itemController.js",line:28,params:["req: AuthenticatedRequest","res: Response"],calls:["validateItemData()","Item.create()"],calledBy:["itemRoutes.js:21 after authenticate()"],apiEndpoint:"POST /api/items",dbOperation:"Delegates to Firebase Firestore collection write",branchConditions:["if (!validation.isValid) -> res.status(400).json({ errors })","if (database error) -> res.status(500).json({ error })"],errorHandling:"Encapsulated in try/catch block; logs stack trace and returns sanitized client error.",summary:"Extracts request body, coordinates business validation, constructs model instance, and dispatches to database.",codeSnippet:`// backend/controllers/itemController.js:28
import Item from '../models/Item.js';
import { validateItemData } from './validation.js';

export async function createItem(req, res) {
  try {
    const { title, description, category, location, dateLost, imageUrl } = req.body;

    const validation = validateItemData({ title, category, location });
    if (!validation.isValid) {
      return res.status(400).json({ success: false, errors: validation.errors });
    }

    const newItem = await Item.create({
      reporter: req.user.id,
      title: title.trim(),
      description: description || '',
      category,
      location,
      dateLost: dateLost || new Date(),
      status: 'reported',
      imageUrl: imageUrl || null
    });

    return res.status(201).json({
      success: true,
      message: 'Item registered successfully.',
      item: newItem
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
}`},{id:"step_7",stepNumber:7,name:"Validate item data (Firestore Schema)",type:"model_validation",category:"Model & Schema Guard",filePath:"backend/models/Item.js",line:32,params:["docData: ItemPayload"],calls:["validateFirestoreDocument()"],calledBy:["createItem() in itemController.js:40"],apiEndpoint:"N/A",dbOperation:"Pre-save schema validation check",branchConditions:["title: required, minlength: 3, maxlength: 120",'category: enum ["electronics", "documents", "clothing", "keys", "other"]',"location: required, trim"],errorHandling:"ValidationError thrown if any field fails Firestore document constraints.",summary:'Validates document attributes, applies default fields (status="reported"), and enforces schema types for Firestore.',codeSnippet:`// backend/models/Item.js:32
export function validateItem(doc) {
  if (!doc.title || doc.title.length < 3) throw new Error('Title is required');
  if (!['electronics', 'documents', 'clothing', 'keys', 'other'].includes(doc.category)) {
    throw new Error('Invalid item category');
  }
  return {
    ...doc,
    status: doc.status || 'reported',
    createdAt: new Date()
  };
}`},{id:"step_8",stepNumber:8,name:"Save item in Firebase Firestore",type:"database",category:"Database Storage",filePath:"Firebase Firestore / items collection",line:1,params:["document: Firestore Document"],calls:['db.collection("items").add()'],calledBy:["Firebase Admin SDK / Firestore Client"],apiEndpoint:"N/A",dbOperation:'Firestore write -> collection("items").doc(id).set(data)',branchConditions:["Document validation; security rules authorization check"],errorHandling:"Permission denied or quota limit error triggers FirebaseFirestoreError.",summary:"Database persists document to Firebase Cloud Firestore, allocates unique document ID, and syncs indexes.",codeSnippet:`// Firebase Cloud Firestore Engine Operation:
